import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, color } from 'three/tsl';
import { gsap } from 'gsap';

/**
 * @typedef {Object} NodeConfig
 * @typedef {Object} NodeContext
 */

/**
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {import('three').Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector3 } = ctx.THREE;

  // ---------- Helper ----------
  const hex = (v) => Number.parseInt(v.replace('#', ''), 16);
  const toColor = (hexStr) => {
    const h = hex(hexStr);
    const r = ((h >> 16) & 255) / 255;
    const g = ((h >> 8) & 255) / 255;
    const b = (h & 255) / 255;
    return { r, g, b };
  };

  // ---------- Colors ----------
  const COLORS = {
    background: '#0b0b10',
    surface: '#101015',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    hairline: '#23232b',
    gradientTop: '#121218',
    gradientBottom: '#0b0b10',
  };

  // ---------- Geometry ----------
  const WIDTH = 6.8;
  const HEIGHT = 2.0;
  const planeGeo = new PlaneGeometry(WIDTH, HEIGHT);

  // ---------- Main Backdrop Material ----------
  const backdropMat = new MeshStandardNodeMaterial();
  backdropMat.colorNode = mix(color(COLORS.gradientTop), color(COLORS.gradientBottom), uv().y);
  backdropMat.roughness = 0.6;
  backdropMat.metalness = 0.2;
  backdropMat.transparent = true;
  backdropMat.depthWrite = true;
  const backdrop = new Mesh(planeGeo, backdropMat);
  backdrop.name = 'backdrop';
  backdrop.receiveShadow = true;

  // ---------- Hairline Rules ----------
  const hairlineGeo = new PlaneGeometry(WIDTH, 0.006);
  const hairlineMat = new MeshStandardNodeMaterial();
  hairlineMat.color = new ctx.THREE.Color(COLORS.hairline);
  hairlineMat.roughness = 0.8;
  hairlineMat.metalness = 0.0;
  hairlineMat.transparent = true;

  const topHairline = new Mesh(hairlineGeo, hairlineMat);
  topHairline.position.set(0, HEIGHT / 2 - 0.003, 0.001);
  const bottomHairline = new Mesh(hairlineGeo, hairlineMat);
  bottomHairline.position.set(0, -HEIGHT / 2 + 0.003, 0.001);

  // ---------- Accent Bar ----------
  const accentBarGeo = new PlaneGeometry(0.3, 0.02);
  const accentBarMat = new MeshStandardNodeMaterial();
  accentBarMat.color = new ctx.THREE.Color(COLORS.accent);
  accentBarMat.emissive = new ctx.THREE.Color(COLORS.accent);
  accentBarMat.emissiveIntensity = 1.4;
  accentBarMat.roughness = 0.6;
  accentBarMat.metalness = 0.2;
  accentBarMat.transparent = true;
  const accentBar = new Mesh(accentBarGeo, accentBarMat);
  // Will be positioned after wordmark creation

  // ---------- Text ----------
  const FONT_OPTS = (size, colorHex, weight, lineHeight, letterSpacing) => ({
    fontSize: size,
    color: colorHex,
    align: 'left',
    lineHeight,
    letterSpacing,
  });

  const group = new Group();
  group.add(backdrop, topHairline, bottomHairline, accentBar);

  // Layout calculations
  const leftEdge = -WIDTH / 2;
  const blockLeftWidth = 2.0;
  const gutter = 0.375;
  const columnWidth = 1.2;

  // Wordmark
  const wordmarkOpts = {
    fontSize: 34,
    color: COLORS.ink,
    align: 'left',
  };
  const wordmark = ctx.fontAtlas.createText('NOVA ATELIER', wordmarkOpts);
  wordmark.position.set(leftEdge + blockLeftWidth / 2 - 0.4, 0.35, 0);
  group.add(wordmark);

  // Accent bar positioning (beneath wordmark)
  accentBar.position.set(wordmark.position.x, wordmark.position.y - 0.1, 0.001);

  // Column positions (centers)
  const firstColX = leftEdge + blockLeftWidth + gutter / 2 + columnWidth / 2;
  const secondColX = firstColX + columnWidth + gutter;
  const thirdColX = secondColX + columnWidth + gutter;
  const columnXs = [firstColX, secondColX, thirdColX];

  // Column Header options
  const headerOpts = {
    fontSize: 9,
    color: COLORS.ink,
    align: 'left',
    fontWeight: 700,
    letterSpacing: 0.12,
    lineHeight: 1.2,
  };
  // Link options (default)
  const linkOptsDefault = {
    fontSize: 13,
    color: COLORS.paper,
    align: 'left',
    fontWeight: 400,
    lineHeight: 1.8,
    letterSpacing: 0,
  };

  // Content definition per column
  const columns = [
    {
      header: 'ATELIER',
      links: ['Features', 'Collection', 'Pricing'],
    },
    {
      header: 'COMPANY',
      links: ['Journal', 'Visit the Atelier', 'Contact'],
    },
    {
      header: 'LEGAL',
      links: ['Privacy', 'Terms', 'Warranty'],
    },
  ];

  const linkHoverTimelines = [];

  columns.forEach((col, idx) => {
    const baseX = columnXs[idx];
    let cursorY = 0.2; // start a bit below wordmark level

    // Header
    const header = ctx.fontAtlas.createText(col.header, {
      fontSize: headerOpts.fontSize,
      color: headerOpts.color,
      align: 'left',
      lineHeight: headerOpts.lineHeight,
      letterSpacing: headerOpts.letterSpacing,
    });
    header.position.set(baseX - columnWidth / 2 + 0.05, cursorY, 0);
    group.add(header);
    cursorY -= headerOpts.lineHeight * 0.13; // approximate spacing

    // Links
    col.links.forEach((linkText) => {
      const link = ctx.fontAtlas.createText(linkText, linkOptsDefault);
      link.position.set(baseX - columnWidth / 2 + 0.05, cursorY, 0);
      group.add(link);

      // Hover handling
      const material = (() => {
        let mat = null;
        link.traverse((obj) => {
          if (obj.isMesh && obj.material) mat = obj.material;
        });
        return mat;
      })();

      if (material) {
        const originalColor = material.color.clone();
        const hoverColor = new ctx.THREE.Color(COLORS.accent);
        const hoverTimeline = gsap.timeline({ paused: true });
        hoverTimeline
          .to(
            material.color,
            {
              r: hoverColor.r,
              g: hoverColor.g,
              b: hoverColor.b,
              duration: 0.14,
              ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
            },
            0
          )
          .to(
            link.position,
            { z: 0.02, duration: 0.14, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
            0
          );
        linkHoverTimelines.push(hoverTimeline);

        // expose handlers
        link.userData.handlers = link.userData.handlers || {};
        link.userData.handlers.hover = (isHover) => {
          if (isHover) {
            hoverTimeline.play(0);
          } else {
            // revert color
            gsap.to(material.color, {
              r: originalColor.r,
              g: originalColor.g,
              b: originalColor.b,
              duration: 0.14,
              ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
            });
            gsap.to(link.position, {
              z: 0,
              duration: 0.14,
              ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
            });
            hoverTimeline.pause(0);
          }
        };
      }

      cursorY -= linkOptsDefault.lineHeight * 0.13; // spacing between links
    });
  });

  // Legal line (full width)
  const legalOpts = {
    fontSize: 9,
    color: COLORS.paper,
    align: 'center',
    lineHeight: 1.4,
    letterSpacing: 0.04,
  };
  const legalText = ctx.fontAtlas.createText(
    '(c) 2026 Nova Atelier. All rights reserved. Machined in Geneva.',
    legalOpts
  );
  legalText.position.set(0, -HEIGHT / 2 + 0.25 + 0.003, 0);
  group.add(legalText);

  // ---------- Fade‑up Animation ----------
  const fadeTimeline = gsap.timeline();
  // start slightly above and invisible
  group.position.y += 0.2;
  group.traverse((obj) => {
    if (obj.isMesh && obj.material) {
      obj.material.transparent = true;
      obj.material.opacity = 0;
    }
  });
  fadeTimeline.fromTo(
    group.position,
    { y: group.position.y },
    { y: group.position.y - 0.2, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
    0
  );
  fadeTimeline.fromTo(
    group,
    { userData: { dummy: 0 } },
    {
      userData: { dummy: 1 },
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      onUpdate: () => {
        group.traverse((obj) => {
          if (obj.isMesh && obj.material && 'opacity' in obj.material) {
            obj.material.opacity = obj.material.opacity + 0.02; // incremental approximate
          }
        });
      },
    },
    0
  );

  // ---------- Cleanup ----------
  group.userData.cleanup = () => {
    fadeTimeline.kill();
    linkHoverTimelines.forEach((t) => t.kill());
    // dispose geometries & materials
    const disposeRec = (obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) {
        if (Array.isArray(obj.material)) {
          obj.material.forEach((m) => m.dispose());
        } else {
          obj.material.dispose();
        }
      }
      if (obj.children) obj.children.forEach(disposeRec);
    };
    disposeRec(group);
  };

  // ---------- Handlers Container ----------
  group.userData.handlers = {};

  return group;
}
